    }
    public function recoverJournal(){
        $file=$this->root.'/recovery.json';if(!is_file($file))return;$j=$this->read($file);$id=$this->id(isset($j['id'])?$j['id']:null);$work=$this->root.'/staging/'.$id;$undo=$work.'/old_uploads';if($j['work']!==$work||$j['undo']!==$undo)throw new RuntimeException('El registro de recuperación no coincide con sus rutas.');$q=$this->db->prepare('SELECT id FROM sistema_recuperacion WHERE id=?');$q->execute(array($id));$done=(bool)$q->fetchColumn();
